window.BANCO = window.BANCO || [];
window.BANCO.push({"id":"excel","nombre":"Tema 5 · Excel 365","bloques":[{"id":"excel-general","nombre":"Excel 365"}],"calendarios":{},"casos":[{"id":"test-x-of-01","titulo":"Oficial 1","texto":"","corto":true,"ids":["x-of-01-001","x-of-01-002","x-of-01-003","x-of-01-004","x-of-01-005"]},{"id":"test-x-ex-01","titulo":"Examen 1","texto":"","corto":true,"ids":["x-ex-01-001","x-ex-01-002","x-ex-01-003","x-ex-01-004","x-ex-01-005","x-ex-01-006","x-ex-01-007","x-ex-01-008","x-ex-01-009","x-ex-01-010","x-ex-01-011","x-ex-01-012","x-ex-01-013","x-ex-01-014","x-ex-01-015"]},{"id":"test-x-in-01","titulo":"INAP 2019 ord.","texto":"","corto":true,"ids":["x-in-01-055","x-in-01-056","x-in-01-057","x-in-01-059","x-in-01-060"]},{"id":"test-x-in-02","titulo":"INAP 2019 extra","texto":"","corto":true,"ids":["x-in-02-056","x-in-02-057","x-in-02-064"]},{"id":"test-x-in-03","titulo":"INAP 2022 ord.","texto":"","corto":true,"ids":["x-in-03-053","x-in-03-054"]},{"id":"test-x-in-04","titulo":"INAP 2022 extra","texto":"","corto":true,"ids":["x-in-04-057","x-in-04-058","x-in-04-059","x-in-04-060"]},{"id":"test-x-in-05","titulo":"INAP 14 dic. 2024","texto":"","corto":true,"ids":["x-in-05-058","x-in-05-059","x-in-05-060","x-in-05-067"]},{"id":"test-x-in-06","titulo":"INAP 2024 extra","texto":"","corto":true,"ids":["x-in-06-062","x-in-06-063"]},{"id":"test-x-in-07","titulo":"INAP 23 mayo 2026","texto":"","corto":true,"ids":["x-in-07-055","x-in-07-056","x-in-07-057","x-in-07-058"]},{"id":"test-x-in-08","titulo":"INAP julio 2026 extra","texto":"","corto":true,"ids":["x-in-08-056","x-in-08-057","x-in-08-058"]}],"preguntas":[{"id":"x-au-01-001","origen":"autoevaluacion","test":"Autoevaluación 1","n":1,"enunciado":"¿Qué elemento de la interfaz de Excel permite acceder rápidamente a funciones como Guardar, Deshacer y Rehacer?","opciones":["c) Barra de herramientas de acceso rápido","b) Cinta de opciones","a) Barra de estado","d) Panel de navegación"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de herramientas de acceso rápido (pág. 2)","justificaciones":["Es esta. La **barra de herramientas de acceso rápido** muestra los botones Guardar, Deshacer, Rehacer y el selector de Autoguardado. Se puede colocar encima o debajo de la cinta.","No. La **cinta de opciones** agrupa todas las herramientas en fichas y grupos. No es el acceso rápido a Guardar, Deshacer y Rehacer.","No. La **barra de estado** muestra el estado de Excel, los modos de vista y el zoom.","No. El panel de navegación es de Word, no una parte de la interfaz de Excel."]},{"id":"x-au-01-002","origen":"autoevaluacion","test":"Autoevaluación 1","n":2,"enunciado":"¿Qué ocurre al pulsar ALT + Q en Excel 365?","opciones":["b) Se muestra el historial de versiones","a) Se guarda automáticamente el archivo","d) Se abre la caja de búsqueda","c) Se activa la celda activa"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Caja de búsqueda (pág. 3)","justificaciones":["No. El historial de versiones se abre desde Archivo > Información o desde el nombre del libro en la barra de título.","No. Guardar es **Ctrl + G**. El Autoguardado tiene su selector en la barra de acceso rápido.","Es esta. **Alt + Q** lleva a la **caja de búsqueda**, integrada en la barra de título.","No. La celda activa no se activa con atajo: es la que seleccionas."]},{"id":"x-au-01-003","origen":"autoevaluacion","test":"Autoevaluación 1","n":3,"enunciado":"¿Cuál de estas afirmaciones sobre el historial de versiones es cierta?","opciones":["a) Solo está disponible si el archivo se ha compartido en la nube","b) Las versiones se abren en modo edición","d) Solo muestra las dos últimas versiones guardadas","c) Las versiones se visualizan en un panel lateral en modo solo lectura"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Historial de versiones (págs. 3 y 4)","justificaciones":["Es esta. El **Historial de versiones** solo está disponible si el archivo está almacenado en la nube, en **OneDrive**.","No. Al abrir una versión, se abre en una nueva ventana y para volver a trabajar sobre ella hay que pulsar “Restaurar”. No se abre en modo edición.","No. El panel lista las versiones anteriores que han sido conservadas, no solo las dos últimas.","No. Aunque en parte es cierta (el libro se abre en solo lectura y el panel de versiones aparece a la derecha), la plantilla da como correcta la A. Consulta el aviso de revisión."],"revisar":"La opción 3 también parece verdadera según los apuntes (págs. 3 y 4): el libro se abre en modo solo lectura y el panel de versiones se muestra a la derecha. Se mantiene la respuesta de la plantilla (la 0), que también es cierta si se entiende la nube como OneDrive."},{"id":"x-au-01-004","origen":"autoevaluacion","test":"Autoevaluación 1","n":4,"enunciado":"¿Qué es una celda en Excel?","opciones":["c) La intersección entre una fila y una columna","b) El cuadro de nombres de cada hoja","a) La unión entre dos filas","d) Un conjunto de fórmulas relacionadas"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["Es esta. Una **celda** es la intersección de una fila y una columna. Su nombre es la columna seguida de la fila, como A1.","No. El cuadro de nombres muestra el nombre de la celda activa, pero no es la celda.","No. La unión de dos filas no es una celda.","No. Un conjunto de fórmulas relacionadas no define una celda."]},{"id":"x-au-01-005","origen":"autoevaluacion","test":"Autoevaluación 1","n":5,"enunciado":"¿Qué extensión corresponde a un libro de Excel habilitado para macros?","opciones":["b) .xlsb","d) .xltx","c) .xlsm","a) .xlsx"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, formatos de archivo (pág. 5)","justificaciones":["No. **.xlsb** es el libro binario de Excel.","No. **.xltx** es la plantilla de Excel.","Es esta. **.xlsm** es el libro de Excel habilitado para macros.","No. **.xlsx** es el libro normal, sin macros."]},{"id":"x-au-01-006","origen":"autoevaluacion","test":"Autoevaluación 1","n":6,"enunciado":"¿Cuál es la diferencia entre una celda activa y un rango seleccionado?","opciones":["b) La celda activa se ilumina; el rango no","a) No existe diferencia, son lo mismo","c) La celda activa es donde se introduce el dato; el rango es una selección de varias celdas","d) El rango siempre está compuesto por celdas no contiguas"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. Que se ilumine no es la diferencia. Al moverte, se resaltan los encabezados de la columna y la fila de la celda activa.","No. No son lo mismo: la celda activa es una, y el rango son dos o más.","Es esta. La **celda activa** es aquella sobre la que se introducen o modifican datos. El **rango** es una selección de dos o más celdas.","No. Los rangos pueden ser contiguos o discontinuos. El rango habitual es de celdas contiguas."]},{"id":"x-au-01-007","origen":"autoevaluacion","test":"Autoevaluación 1","n":7,"enunciado":"¿Cómo se denomina el rango que va desde la celda A1 hasta la celda C6?","opciones":["b) Rango A1C6","d) Rango A1:C6","a) Rango A1-A6","c) Rango A1;C6"],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. “A1C6” no es una forma válida de nombrar un rango, y se parece a una referencia F1C1.","Es esta. Un rango se nombra con la celda superior izquierda y la inferior derecha, separadas por dos puntos: **A1:C6**.","No. “A1-A6” no es válido: el guion no separa celdas de un rango, y además A6 no es la esquina inferior derecha.","No. El punto y coma separa áreas distintas en un rango discontinuo, no define un rango continuo."]},{"id":"x-au-01-008","origen":"autoevaluacion","test":"Autoevaluación 1","n":8,"enunciado":"¿Qué sucede si al escribir en una celda ya hay contenido?","opciones":["b) Excel muestra una advertencia","d) El nuevo dato se almacena en el portapapeles","a) Se fusiona el contenido anterior con el nuevo","c) Se elimina el contenido anterior"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 3. Introducción de datos (pág. 12)","justificaciones":["No. Excel no muestra advertencia: sustituye el contenido directamente.","No. El nuevo dato no va al portapapeles, se escribe en la celda.","No. No se fusionan: el contenido anterior se sustituye. Para modificarlo sin borrarlo hay que usar F2, doble clic o la barra de fórmulas.","Es esta. Si comienzas a escribir en una celda que ya contiene información, el contenido anterior será **sustituido** por el nuevo."]},{"id":"x-au-01-009","origen":"autoevaluacion","test":"Autoevaluación 1","n":9,"enunciado":"En relación con los diferentes formatos de archivo disponibles en Microsoft Excel 365, señale cuál de las siguientes asociaciones entre el tipo de documento y su extensión es correcta:","opciones":["Libro binario de Excel — .xlsx.","Libro de Excel 97-2003 — .xlt.","Libro habilitado para macros — .xlsb.","Plantilla de Excel — .xltx."],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, formatos de archivo (pág. 5)","justificaciones":["No. El libro binario es **.xlsb**, no .xlsx.","No. El libro de Excel 97-2003 es **.xls**. La extensión .xlt es la plantilla de Excel 97-2003.","No. El libro habilitado para macros es **.xlsm**. El .xlsb es el binario.","Es esta. La plantilla de Excel es **.xltx**."]},{"id":"x-au-01-010","origen":"autoevaluacion","test":"Autoevaluación 1","n":10,"enunciado":"Al iniciar Microsoft Excel 365 y crear varios libros nuevos en blanco, sin modificar sus nombres predeterminados, ¿cuál de las siguientes afirmaciones es correcta?","opciones":["Los libros reciben inicialmente los nombres Libro1, Libro2, Libro3, y así sucesivamente.","Excel asigna automáticamente el nombre Documento1, Documento2, Documento3, y así sucesivamente.","Excel no asigna ningún nombre al libro hasta que el usuario lo guarda por primera vez.","Todos los libros reciben inicialmente el nombre Hoja1, que se modifica al guardar el archivo."],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de título (pág. 2)","justificaciones":["Es esta. Los libros reciben el nombre por defecto **Libro1**, Libro2, Libro3...","No. Documento1, Documento2... es el nombre por defecto en Word.","No. Excel sí asigna un nombre desde el principio: Libro1.","No. Hoja1 es el nombre de la hoja, no del libro."]},{"id":"x-au-02-001","origen":"autoevaluacion","test":"Autoevaluación 2","n":1,"enunciado":"¿Cuál de los siguientes formatos de archivo no admite Excel?","opciones":["d) .bmp","a) .xlsx","b) .xlt","c) .ods"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, formatos de archivo (pág. 5)","justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. **.bmp** es un formato de imagen. Excel no lo admite como formato de libro.","Es verdadera, así que no se marca. **.xlsx** es el libro de Excel.","Es verdadera, así que no se marca. **.xlt** es la plantilla de Excel 97-2003.","Es verdadera, así que no se marca. **.ods** es la hoja de cálculo de OpenDocument."]},{"id":"x-au-02-002","origen":"autoevaluacion","test":"Autoevaluación 2","n":2,"enunciado":"El cuadro de nombres cuenta con numerosas utilidades, ¿cuál no es una de ellas?","opciones":["d) Nombrar un libro","c) Mostrar el nombre de la celda activa","b) Nombrar un rango","a) Desplazarnos a una celda"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Cuadro de nombres (págs. 7 y 8)","justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El cuadro de nombres no nombra libros. El nombre del libro se cambia desde la barra de título.","Es verdadera, así que no se marca. Muestra el nombre de la celda activa.","Es verdadera, así que no se marca. Permite nombrar un rango de celdas.","Es verdadera, así que no se marca. Permite desplazarnos a una celda en concreto."]},{"id":"x-au-02-003","origen":"autoevaluacion","test":"Autoevaluación 2","n":3,"enunciado":"¿En qué parte de la interfaz de Excel 365 se muestra el contenido real de una celda?","opciones":["b) En la barra de estado","a) En el cuadro de nombres","c) En la cinta de opciones","d) En la barra de fórmulas"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de fórmulas (pág. 8)","justificaciones":["No. La barra de estado indica el estado de Excel, los modos de vista y el zoom.","No. El cuadro de nombres muestra el nombre de la celda activa, no su contenido.","No. La cinta de opciones tiene las herramientas, no el contenido de las celdas.","Es esta. La **barra de fórmulas** muestra el contenido de la celda seleccionada y permite modificarlo."]},{"id":"x-au-02-004","origen":"autoevaluacion","test":"Autoevaluación 2","n":4,"enunciado":"Hay tres vistas disponibles en la barra de estado de Excel. ¿Cuál no es una de ellas?","opciones":["d) Vista previa de salto de página","c) Diseño de página","b) Pantalla completa","a) Normal"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de estado (pág. 9)","justificaciones":["Es verdadera, así que no se marca. **Vista previa de salto de página** es uno de los modos de vista.","Es verdadera, así que no se marca. **Diseño de página** es uno de los modos de vista.","Esta es la falsa, y por eso es la que hay que marcar. “Pantalla completa” no es un modo de vista de la barra de estado. Los tres son Normal, Diseño de página y Vista previa de salto de página.","Es verdadera, así que no se marca. **Normal** es uno de los modos de vista."]},{"id":"x-au-02-005","origen":"autoevaluacion","test":"Autoevaluación 2","n":5,"enunciado":"¿Qué es un rango?","opciones":["d) Conjunto de dos o más celdas contiguas","c) Las hojas por las que está formado un libro de Excel","b) Conjunto de filas con el mismo estilo","a) Intersección de una fila y una columna"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["Es esta. Un **rango** es la selección de dos o más celdas contiguas.","No. Las hojas de las que se compone un libro son las hojas, no un rango.","No. Un conjunto de filas con el mismo estilo no es un rango.","No. La intersección de una fila y una columna es una **celda**."]},{"id":"x-au-02-006","origen":"autoevaluacion","test":"Autoevaluación 2","n":6,"enunciado":"¿Cuál de los siguientes nombres de rango es correcto?","opciones":["b) A1.6C","c) C6:A1","a) 1A:C6","d) A1:C6"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. “A1.6C” no es un nombre válido: el punto no separa celdas de un rango.","No. C6:A1 pone la esquina inferior derecha primero. El rango se nombra con la celda superior izquierda y la inferior derecha, por este orden.","No. “1A” tiene el orden al revés: la referencia es primero la columna y luego la fila.","Es esta. **A1:C6** va de la celda superior izquierda a la inferior derecha, separadas por dos puntos."]},{"id":"x-au-02-007","origen":"autoevaluacion","test":"Autoevaluación 2","n":7,"enunciado":"Podemos realizar distintas operaciones si pulsamos con el botón secundario de nuestro ratón sobre el nombre de una hoja de Excel. ¿Cuál de las siguientes no es correcta?","opciones":["a) Cambiar el nombre de la hoja","c) Mostrar una hoja","d) Ocultar una hoja","b) Eliminar el libro"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, etiquetas de hoja (pág. 7)","justificaciones":["Es verdadera, así que no se marca. **Cambiar nombre** está en el menú de la etiqueta de hoja.","Es verdadera, así que no se marca. **Mostrar** hojas ocultas está en el menú de la etiqueta de hoja.","Es verdadera, así que no se marca. **Ocultar** la hoja está en el menú de la etiqueta de hoja.","Esta es la falsa, y por eso es la que hay que marcar. Del menú de la hoja se puede eliminar la **hoja**, no el libro entero."]},{"id":"x-au-02-008","origen":"autoevaluacion","test":"Autoevaluación 2","n":8,"enunciado":"Para desplazarnos en la hoja de calculo hacia la derecha utilizamos la tecla…","opciones":["a) Intro","c) Tab","b) May + Intro","d) May + Tab"],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 3. Desplazamiento por la hoja (pág. 9)","justificaciones":["No. **Intro** desplaza hacia abajo.","Es esta. Para desplazarse hacia la derecha, además de la flecha, se pulsa **Tab**.","No. **Mayús + Intro** desplaza hacia arriba.","No. **Mayús + Tab** desplaza hacia la izquierda."]},{"id":"x-au-02-009","origen":"autoevaluacion","test":"Autoevaluación 2","n":9,"enunciado":"En relación con los distintos elementos que componen la interfaz de Microsoft Excel 365, señale la afirmación correcta:","opciones":["La barra de fórmulas permite visualizar y modificar el contenido de la celda activa, así como acceder al asistente de funciones mediante el botón Insertar función.","La barra de herramientas de acceso rápido se encuentra exclusivamente integrada en la barra de título y no puede desplazarse debajo de la cinta de opciones.","El cuadro de nombres permite identificar la celda activa y desplazarse a un rango determinado, pero no permite asignar nombres a rangos de celdas.","La caja de búsqueda, integrada en la barra de título, permite buscar comandos y contenido del libro, y se activa mediante la combinación Ctrl + Q."],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel (págs. 2, 3, 7 y 8)","justificaciones":["Es esta. La **barra de fórmulas** muestra el contenido de la celda seleccionada y permite modificarlo. El botón **Insertar función** abre el cuadro de funciones.","No. La barra de acceso rápido puede mostrarse encima de la cinta (en la barra de título) o debajo de ella.","No. El cuadro de nombres sí permite nombrar rangos de celdas, además de mostrar el nombre de la celda activa y desplazarnos a un rango.","No. La caja de búsqueda busca acciones, ayuda y contenido del libro, pero se activa con **Alt + Q**, no con Ctrl + Q."]},{"id":"x-au-02-010","origen":"autoevaluacion","test":"Autoevaluación 2","n":10,"enunciado":"Respecto a la barra de estado de Microsoft Excel 365 y a la información que proporciona durante la edición de una hoja de cálculo, señale la afirmación incorrecta:","opciones":["El estado «Listo» indica que Excel se encuentra en un estado general de reposo, sin que se esté introduciendo o modificando información.","La barra de estado puede configurarse para mostrar cálculos como la suma o el promedio de los valores numéricos de las celdas seleccionadas.","El estado «Señalar» puede aparecer cuando se está construyendo una fórmula y se seleccionan celdas para incorporarlas como referencias.","El estado «Modificar» aparece cuando se introducen datos por primera vez en una celda que se encontraba vacía."],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de estado (págs. 8 y 9)","justificaciones":["Es verdadera, así que no se marca. **Listo** indica el estado general, en reposo.","Es verdadera, así que no se marca. La barra de estado se puede configurar para mostrar cálculos sencillos como la suma o el promedio.","Es verdadera, así que no se marca. **Señalar** aparece al confeccionar una fórmula y seleccionar las celdas.","Esta es la falsa, y por eso es la que hay que marcar. Cuando se escribe por primera vez en una celda vacía aparece **Introducir**. **Modificar** sale al editar una celda que ya tenía contenido."]},{"id":"x-of-01-001","origen":"oficiales","test":"Oficial 1","n":1,"enunciado":"En Excel 365, ¿cuál de los siguientes es un operador válido para comenzar una fórmula en una celda? (AUX ADVO Extraordinario LIBRE 2024)","opciones":["=","/","$","&"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 4.1 Fórmulas y funciones (pág. 12)","justificaciones":["Es esta. Las fórmulas se introducen, de forma estándar, comenzando por el signo **igual (=)**. También se puede empezar con el signo más (+).","No. La barra (/) es el operador de la división, pero no inicia una fórmula.","No. El signo del dólar ($) se usa en las referencias absolutas, como $A$1. No inicia una fórmula.","No. El ampersand (&) es el operador de concatenación de texto. No inicia una fórmula."],"revisar":"Los apuntes (pág. 12) dicen que una fórmula empieza por = o por +. Aquí solo aparece el = entre las opciones. La función de /, $ y & como operadores o símbolos sale del conocimiento general de Excel."},{"id":"x-of-01-002","origen":"oficiales","test":"Oficial 1","n":2,"enunciado":"Señale cómo se denomina al contenido de una celda que NO va precedido del signo igual:(Aux AGE 2016)","opciones":["Fórmula","Función","Variable","Constante"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 4.1 Fórmulas y funciones, valores constantes (pág. 13)","justificaciones":["No. Una **fórmula** empieza por el signo igual (o más).","No. Una **función** es una fórmula predefinida de Excel, con nombre y argumentos, y se introduce dentro de una fórmula con el signo igual.","No. “Variable” no es un tipo de contenido de las celdas de Excel.","Es esta. Un valor **constante** se introduce directamente en la celda, sin el signo igual. Puede ser numérico o de texto."]},{"id":"x-of-01-003","origen":"oficiales","test":"Oficial 1","n":3,"enunciado":"En Excel 365, un grupo de celdas adyacentes se denomina: (AUX ESTABILIZACION 2022)","opciones":["Rango.","Asociación.","Referencia.","Grupo."],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["Es esta. Un **rango** es la selección de dos o más celdas contiguas, y se nombra con la celda superior izquierda y la inferior derecha separadas por dos puntos.","No. “Asociación” no es un término de Excel.","No. La **referencia** es el nombre de una celda individual, como A1.","No. “Grupo” no es el nombre de un conjunto de celdas adyacentes."]},{"id":"x-of-01-004","origen":"oficiales","test":"Oficial 1","n":4,"enunciado":"En Excel 365, al trabajar con rangos, ¿cuál de las siguientes opciones describe correctamente un rango discontinuo?","opciones":["B2:B2","$B$2:$C$4","B2:C4","B2:C2;B4:C4"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. B2:B2 es una sola celda, un rango de una celda.","No. $B$2:$C$4 es un rango continuo, con referencias absolutas.","No. B2:C4 es un rango continuo: todas las celdas son contiguas.","Es esta. Un rango **discontinuo** está formado por dos o más áreas no adyacentes, separadas por punto y coma: **B2:C2;B4:C4**. Se seleccionan con la tecla Ctrl."],"dup":"x-of-01-004"},{"id":"x-of-01-005","origen":"oficiales","test":"Oficial 1","n":5,"enunciado":"En Microsoft Excel 365, si se produce un cierre inesperado del programa o el usuario olvida guardar un libro nuevo antes de cerrar, ¿es posible recuperar dicho archivo?","opciones":["Sí, el programa guarda cada cambio de forma permanente automáticamente, aunque el archivo nunca se haya guardado.","Sí, Excel guarda copias temporales automáticamente que se pueden recuperar desde el menú Archivo > Información > Administrar libro.","Sí, solo si el archivo estaba guardado previamente en un pendrive o disco externo.","No, si no se pulsó el botón \"Guardar\" antes de cerrar, toda la información se pierde sin posibilidad de recuperarla."],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Recuperación de libros no guardados (pág. 4)","justificaciones":["No. Excel no guarda cada cambio de forma permanente automáticamente si el archivo nunca se ha guardado. Lo que existe son copias temporales.","Es esta. Si existen copias temporales de la **Autorrecuperación**, se pueden recuperar desde **Archivo > Información > Administrar libro > Recuperar libros no guardados**.","No. No hace falta que el archivo estuviera en un pendrive o disco externo.","No. Sí es posible recuperarlo, mientras existan las copias temporales de la Autorrecuperación."]},{"id":"x-ex-01-001","origen":"examenes","test":"Examen 1","n":1,"enunciado":"En Excel 365, un grupo de celdas adyacentes ¿cómo se denomina?:","opciones":["Rango.","Asociación.","Referencia.","Grupo."],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["Es esta. Un **rango** es la selección de dos o más celdas contiguas, como A1:C6.","No. “Asociación” no es un término de Excel.","No. La **referencia** es el nombre de una celda concreta, como A1.","No. “Grupo” no es el nombre de un conjunto de celdas adyacentes."]},{"id":"x-ex-01-002","origen":"examenes","test":"Examen 1","n":2,"enunciado":"De los siguientes elementos, ¿cuál NO aparece en la pantalla de inicio de Excel?","opciones":["Libro en blanco.","Plantillas.","Asistente de funciones.","Opciones de Excel."],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, pantalla de inicio (pág. 1) y barra de fórmulas (pág. 8)","justificaciones":["Es verdadera, así que no se marca. El **libro en blanco** aparece en la pantalla de inicio.","Es verdadera, así que no se marca. Las **plantillas** aparecen en la pantalla de inicio.","Esta es la falsa, y por eso es la que hay que marcar. El **asistente de funciones** (el botón Insertar función de la barra de fórmulas) no está en la pantalla de inicio, sino en el área de trabajo.","Es verdadera, así que no se marca. Desde la pantalla de inicio se accede a la cuenta y a las **opciones** del programa."]},{"id":"x-ex-01-003","origen":"examenes","test":"Examen 1","n":3,"enunciado":"Indica cuál es el nombre por defecto de un archivo de Excel:","opciones":["Excel1","Hoja1","Libro1","Lib1"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de título (pág. 2)","justificaciones":["No. “Excel1” no es el nombre por defecto.","No. **Hoja1** es el nombre por defecto de la hoja, no del archivo.","Es esta. El nombre por defecto del archivo es **Libro1**, Libro2, Libro3... Los archivos de Excel se llaman libros.","No. “Lib1” no es el nombre por defecto."],"revisar":"Los apuntes (págs. 1 y 2) dan Libro1 como nombre del libro. Que la hoja se llame Hoja1 por defecto sale del conocimiento general de Excel."},{"id":"x-ex-01-004","origen":"examenes","test":"Examen 1","n":4,"enunciado":"¿Qué cálculo puede realizar Excel para mostrarnos en la barra de estado?","opciones":["Promedio.","Desviación estándar.","Varianza.","Moda."],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de estado (pág. 9)","justificaciones":["Es esta. La barra de estado puede mostrar cálculos sencillos como la **suma** o el **promedio** de los valores numéricos de las celdas seleccionadas.","No. La desviación estándar no es un cálculo de la barra de estado.","No. La varianza no es un cálculo de la barra de estado.","No. La moda no es un cálculo de la barra de estado."],"revisar":"Los apuntes (pág. 9) citan suma y promedio como ejemplo. Que desviación, varianza y moda no se ofrezcan sale de la interfaz de Excel (ofrece promedio, recuento, mínimo, máximo y suma)."},{"id":"x-ex-01-005","origen":"examenes","test":"Examen 1","n":5,"enunciado":"En una celda de Excel, estamos elaborando una fórmula. Para ello, necesitamos añadir la referencia a un rango que va a formar parte de la misma. ¿Qué mensaje nos aparece en la barra de estado?","opciones":["Listo.","Señalar.","Introducir.","Modificar."],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de estado (pág. 8)","justificaciones":["No. **Listo** indica el estado general, cuando Excel está en reposo.","Es esta. **Señalar** aparece cuando estamos confeccionando una fórmula o función y seleccionamos las celdas que formarán parte de ella.","No. **Introducir** aparece cuando empezamos a escribir un contenido nuevo en una celda.","No. **Modificar** aparece cuando editamos los datos de una celda que ya tenía contenido."],"ojo":"Listo (reposo), Introducir (escribes en celda vacía), Modificar (editas celda con contenido), Señalar (eliges celdas para una fórmula)."},{"id":"x-ex-01-006","origen":"examenes","test":"Examen 1","n":6,"enunciado":"Si necesitamos modificar el contenido de una celda de Excel, ¿qué tecla de función podemos usar para ello?","opciones":["F1","F7","F4","F2"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 3. Desplazamiento por la hoja. Introducción de datos (pág. 12)","justificaciones":["No. **F1** abre la ayuda.","No. **F7** abre el corrector ortográfico.","No. **F4** repite la última acción o cambia el tipo de referencia (relativa, absoluta o mixta) al editar una fórmula.","Es esta. **F2** permite modificar los datos existentes en una celda sin sustituir todo su contenido. También se puede con doble clic o desde la barra de fórmulas."],"revisar":"Los apuntes (pág. 12) citan F2 para modificar. Las funciones de F1, F7 y F4 salen del conocimiento general de Excel."},{"id":"x-ex-01-007","origen":"examenes","test":"Examen 1","n":7,"enunciado":"¿Qué ocurre en Excel 365 si pulsamos sobre el botón “Insertar función”, presente en la barra de fórmulas?","opciones":["Inserta un listado con las 10 últimas funciones insertadas en el libro. Si no hay ninguna, muestra un mensaje de error.","Abre el cuadro “Insertar función”, desde donde podemos elegir entre las funciones de Excel disponibles y acceder al asistente de funciones.","Nos lleva a la ficha “Fórmulas” de la cinta de opciones de Excel, para que podamos insertar una de las funciones presentes en la misma.","Muestra en un listado independiente, todas las funciones insertadas en el libro."],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Cuadro de nombres y barra de fórmulas (pág. 8)","justificaciones":["No. No muestra un listado de las últimas 10 funciones ni da ningún error: abre un cuadro de diálogo.","Es esta. El botón **Insertar función** abre el cuadro de diálogo Insertar función, donde buscamos funciones, las seleccionamos por categorías y consultamos su descripción y argumentos.","No. No nos lleva a la ficha Fórmulas: abre su propio cuadro de diálogo.","No. No muestra una lista de las funciones ya insertadas en el libro."]},{"id":"x-ex-01-008","origen":"examenes","test":"Examen 1","n":8,"enunciado":"Señala cuál de las siguientes opciones ESTÁ DISPONIBLE en el menú contextual de la pestaña de hoja en Excel 365:","opciones":["Crear nuevo libro.","Utilizar plantilla.","Seleccionar hoja completa.","Cambiar nombre de la hoja."],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, etiquetas de hoja (pág. 7)","justificaciones":["No. Crear un nuevo libro no está en el menú de la etiqueta de hoja.","No. Utilizar una plantilla no está en el menú de la etiqueta de hoja.","No. El menú permite **seleccionar todas las hojas**, no una “hoja completa”.","Es esta. El menú de la etiqueta de hoja incluye **Cambiar nombre**, además de insertar y eliminar, mover o copiar, ocultar o mostrar, proteger, color de pestaña, seleccionar todas las hojas, vincular y mostrar el panel de cambios."]},{"id":"x-ex-01-009","origen":"examenes","test":"Examen 1","n":9,"enunciado":"La extensión por defecto que asocia Excel al almacenar una hoja de cálculo en un archivo es:","opciones":[".XLTX",".XLSX",".XPS","Excel no tiene asociada extensión por defecto."],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, formatos de archivo (pág. 5)","justificaciones":["No. **.xltx** es la plantilla de Excel.","Es esta. **.xlsx** es la extensión del libro de Excel.","No. **.xps** es un documento XPS, un formato de exportación.","No. Excel sí tiene una extensión por defecto: .xlsx."]},{"id":"x-ex-01-010","origen":"examenes","test":"Examen 1","n":10,"enunciado":"¿Cuál de las siguientes referencias a un rango es correcto?","opciones":["A2.A25","A25:A2","A2:A25","A2..A25"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. Un punto no separa celdas de un rango. Los extremos van con dos puntos.","No. El rango se nombra con la celda superior izquierda y luego la inferior derecha. A25:A2 las pone al revés.","Es esta. El rango se nombra con la celda **superior izquierda** y la **inferior derecha**, separadas por dos puntos: **A2:A25**.","No. Los dos puntos seguidos no son un separador válido."]},{"id":"x-ex-01-011","origen":"examenes","test":"Examen 1","n":11,"enunciado":"¿Cuántas columnas hay en una hoja de cálculo de Excel 365?","opciones":["Desde la A a la XF.","16.384","Depende de la capacidad del equipo.","1.048.576"],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 5)","justificaciones":["No. Las columnas llegan hasta la **XFD**, no hasta la XF.","Es esta. Las columnas van de la A a la XFD, un total de **16.384**.","No. No depende del equipo: es una cifra fija.","No. 1.048.576 es el número de **filas**."]},{"id":"x-ex-01-012","origen":"examenes","test":"Examen 1","n":12,"enunciado":"Si estando seleccionada la celda D6, queremos seleccionar el resto de valores de la columna ¿qué debemos escribir en el cuadro de nombres?","opciones":["C","Columna","D","Seleccionar"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Cuadro de nombres (pág. 8)","justificaciones":["Es esta. Escribir **C** en el cuadro de nombres selecciona la columna completa de la celda activa. Para la fila completa se escribe F.","No. “Columna” no es un comando válido del cuadro de nombres.","No. D es el nombre de la columna, pero escribir solo D no es la forma de seleccionarla.","No. “Seleccionar” no es un comando válido del cuadro de nombres."],"revisar":"Los apuntes (pág. 8, nota 4) indican que se escribe C para la columna y F para la fila, en Excel en español. Que escribir solo D no funcione sale de la práctica con Excel."},{"id":"x-ex-01-013","origen":"examenes","test":"Examen 1","n":13,"enunciado":"¿Cuál de las siguientes acciones enumeradas NO es función del cuadro de nombres de Excel 365?","opciones":["Insertar tablas.","Nombrar rangos.","Seleccionar una columna completa.","Desplazarnos a una celda."],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Cuadro de nombres (págs. 7 y 8)","justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El cuadro de nombres no inserta tablas. Las tablas se insertan desde la cinta, en la ficha Insertar.","Es verdadera, así que no se marca. El cuadro de nombres permite **nombrar un rango** de celdas.","Es verdadera, así que no se marca. Permite seleccionar la fila o la columna de la celda activa.","Es verdadera, así que no se marca. Permite desplazarnos a una celda concreta, incluso de otras hojas."]},{"id":"x-ex-01-014","origen":"examenes","test":"Examen 1","n":14,"enunciado":"¿Cuál de las siguientes referencias a celdas es INCORRECTA?","opciones":["F1C6","1B","A1","B6"],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["Es verdadera, así que no se marca. **F1C6** es una referencia válida en el estilo F1C1: fila 1, columna 6.","Esta es la falsa, y por eso es la que hay que marcar. En el estilo normal la referencia es la **columna seguida de la fila** (B1). “1B” tiene el orden al revés.","Es verdadera, así que no se marca. **A1** es una referencia válida: columna A, fila 1.","Es verdadera, así que no se marca. **B6** es una referencia válida: columna B, fila 6."]},{"id":"x-ex-01-015","origen":"examenes","test":"Examen 1","n":15,"enunciado":"¿Qué extensión utiliza Excel para guardar un libro binario?","opciones":[".XLS",".XLB",".XLSB",".XLSM"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, formatos de archivo (pág. 5)","justificaciones":["No. **.xls** es el libro de Excel 97-2003.","No. **.xlb** no es la extensión de un libro binario de Excel.","Es esta. **.xlsb** es el libro binario de Excel.","No. **.xlsm** es el libro habilitado para macros."]},{"id":"x-vo-01-001","origen":"votaciones","test":"Votaciones clase 1","n":1,"enunciado":"¿Qué tipo de programa es Microsoft Excel 365?","opciones":["a) Navegador web.","b) Hoja de cálculo.","c) Procesador de texto.","d) Gestor de bases de datos."],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 1. ¿Qué es Excel? (pág. 1)","justificaciones":["No. Un navegador web sirve para ver páginas de internet.","Es esta. Excel es una **hoja de cálculo**: organiza y analiza datos, y hace cálculos con fórmulas y funciones.","No. Un procesador de texto es Word.","No. Un gestor de bases de datos es Access."]},{"id":"x-vo-01-002","origen":"votaciones","test":"Votaciones clase 1","n":2,"enunciado":"¿Cuál es el nombre por defecto de un libro de Excel?","opciones":["a) Hoja1","b) Documento1","c) Libro1","d) Base1"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de título (pág. 2)","justificaciones":["No. **Hoja1** es el nombre por defecto de la hoja, no del libro.","No. **Documento1** es el nombre por defecto en Word.","Es esta. El nombre por defecto del libro es **Libro1**, y luego Libro2, Libro3...","No. “Base1” no es un nombre por defecto de Excel."]},{"id":"x-vo-01-003","origen":"votaciones","test":"Votaciones clase 1","n":3,"enunciado":"¿Cuál de las siguientes afirmaciones sobre la “caja de búsqueda” en Excel 365 es correcta?","opciones":["a) Solo permite buscar acciones recientes realizadas en el libro actual.","b) Es una función ubicada en la barra de fórmulas que permite buscar celdas por su contenido.","c) Ofrece resultados que incluyen acciones recientes, sugerencias, ayuda y búsqueda dentro del libro.","d) Solo está disponible si el archivo está almacenado en OneDrive."],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Caja de búsqueda (pág. 3)","justificaciones":["No. No se limita a acciones recientes: también ofrece acciones sugeridas, ayuda y búsqueda en el libro.","No. La caja de búsqueda está integrada en la barra de título, no en la barra de fórmulas.","Es esta. La **caja de búsqueda** recupera acciones realizadas recientemente, acciones sugeridas, búsqueda en la ayuda y búsqueda en el libro. Se accede con **Alt + Q**.","No. Está disponible siempre, no solo con archivos en OneDrive."]},{"id":"x-vo-01-004","origen":"votaciones","test":"Votaciones clase 1","n":4,"enunciado":"¿Dónde se encuentra la opción para restaurar una versión anterior de un libro en Excel 365?","opciones":["a) En la ficha “Inicio”, grupo “Historial”.","b) En la opción “Archivo > Información” o haciendo clic sobre el nombre del libro en la barra de título.","c) En la barra de herramientas de acceso rápido, mediante el botón “Restaurar”.","d) Dentro de la ficha “Datos”, grupo “Herramientas de datos”."],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Historial de versiones (pág. 3)","justificaciones":["No. En la ficha Inicio no hay un grupo Historial.","Es esta. El **Historial de versiones** se abre desde **Archivo > Información** o haciendo clic sobre el nombre del libro en la barra de título. Solo está disponible si el archivo está en OneDrive.","No. La barra de acceso rápido no tiene un botón Restaurar por defecto.","No. En la ficha Datos, el grupo Herramientas de datos trata de validar, quitar duplicados, etc."]},{"id":"x-vo-01-005","origen":"votaciones","test":"Votaciones clase 1","n":5,"enunciado":"¿Qué extensión por defecto tiene un libro de Excel 365?","opciones":["a) .xls","b) .xml","c) .xlsm","d) .xlsx"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, formatos de archivo (pág. 5)","justificaciones":["No. **.xls** es el formato de Excel 97-2003.","No. **.xml** no es la extensión por defecto del libro.","No. **.xlsm** es el libro habilitado para macros.","Es esta. **.xlsx** es la extensión por defecto de un libro de Excel."]},{"id":"x-vo-01-006","origen":"votaciones","test":"Votaciones clase 1","n":6,"enunciado":"¿Cuál es la extensión de una plantilla de Excel?","opciones":["a) .xlsx","b) .xlt","c) .xltx","d) .xlmt"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, formatos de archivo (pág. 5)","justificaciones":["No. **.xlsx** es el libro normal, no la plantilla.","No. **.xlt** es la plantilla de Excel 97-2003, la antigua.","Es esta. **.xltx** es la plantilla de Excel (la t de “template”). Con macros es .xltm.","No. **.xlmt** no existe como extensión de Excel."]},{"id":"x-vo-01-007","origen":"votaciones","test":"Votaciones clase 1","n":7,"enunciado":"¿Qué tipo de archivo de Excel se corresponde con la extensión .xlsm?","opciones":["a) Libro habilitado para macros","b) Libro de Excel para versiones 97-2003","c) Plantilla de Excel","d) Libro de Excel para versiones 97-2003"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, formatos de archivo (pág. 5)","justificaciones":["Es esta. **.xlsm** es el libro de Excel habilitado para macros.","No. El libro de Excel 97-2003 es **.xls**.","No. La plantilla de Excel es **.xltx**.","No. El libro de Excel 97-2003 es **.xls**. Esta opción repite lo mismo que la B."],"revisar":"Las opciones B y D dicen exactamente lo mismo (libro de Excel 97-2003); parece un error de la plantilla, pero no afecta a la respuesta correcta."},{"id":"x-vo-01-008","origen":"votaciones","test":"Votaciones clase 1","n":8,"enunciado":"En una hoja de cálculo Excel, por el concepto de rango se entiende el: (Aux AGE 2005)","opciones":["a) Grupo de celdas que contienen valores numéricos, referenciados por la dirección de cada una de las celdas.","b) Dos o más celdas de una hoja.","c) Grupo de celdas contiguas.","d) Grado de complejidad asociado a una fórmula matricial."],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. Un rango no exige que las celdas tengan valores numéricos. Puede contener cualquier cosa.","No. Un rango son celdas contiguas. Dos celdas cualesquiera de una hoja no forman un rango por sí solas.","Es esta. Un **rango** es un grupo de celdas **contiguas**. Se nombra con la celda superior izquierda y la inferior derecha.","No. El grado de complejidad de una fórmula matricial no tiene que ver con el rango."],"revisar":"Los apuntes (pág. 6) definen rango como la selección de dos o más celdas contiguas, y añaden que también pueden ser discontinuos. La opción 1 (dos o más celdas) no exige que sean contiguas."},{"id":"x-vo-01-009","origen":"votaciones","test":"Votaciones clase 1","n":9,"enunciado":"¿Cuál de las siguientes referencias a un rango es correcto? (Aux AGE 2006)","opciones":["a) A1;D6","b) A1:D6","c) A1&D6","d) A1.D6"],"correcta":1,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. El punto y coma separa áreas distintas en un rango discontinuo, no define un rango continuo entre A1 y D6.","Es esta. El rango se escribe con la celda superior izquierda y la inferior derecha separadas por dos puntos: **A1:D6**.","No. El ampersand (&) concatena texto, no define rangos.","No. Un punto no es el separador de un rango."]},{"id":"x-vo-01-010","origen":"votaciones","test":"Votaciones clase 1","n":10,"enunciado":"En Excel 365, un grupo de celdas adyacentes se denomina:","opciones":["a) Referencia.","b) Asociación.","c) Rango.","d) Grupo."],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. La **referencia** es el nombre de una celda concreta, como A1.","No. “Asociación” no es un término de Excel.","Es esta. Un **rango** es la selección de celdas contiguas, como A1:C6.","No. “Grupo” no es el nombre de un conjunto de celdas adyacentes."]},{"id":"x-vo-01-011","origen":"votaciones","test":"Votaciones clase 1","n":11,"enunciado":"De las siguientes opciones enumeradas, ¿cuál NO está disponible en el menú contextual de una etiqueta de hoja?","opciones":["a) Insertar","b) Proteger hoja","c) Color de pestaña","d) Guardar hoja"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, etiquetas de hoja (pág. 7)","justificaciones":["Es verdadera, así que no se marca. **Insertar** está en el menú de la etiqueta de hoja.","Es verdadera, así que no se marca. **Proteger hoja** está en el menú de la etiqueta de hoja.","Es verdadera, así que no se marca. **Color de pestaña** está en el menú de la etiqueta de hoja.","Esta es la falsa, y por eso es la que hay que marcar. “Guardar hoja” no está en el menú de la etiqueta. Se guarda el libro entero, no una hoja suelta."]},{"id":"x-vo-01-012","origen":"votaciones","test":"Votaciones clase 1","n":12,"enunciado":"¿Cuáles son los límites mínimo y máximo del zoom en Excel?","opciones":["a) 10%-300%","b) 1%-400%","c) 10%-500%","d) 10%-400%"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de estado (pág. 9)","justificaciones":["No. El máximo es 400%, no 300%.","No. El mínimo es 10%, no 1%.","No. El máximo de 500% es el del zoom de Word. En Excel es 400%.","Es esta. En Excel el zoom va del **10%** al **400%**."],"ojo":"Zoom en Word: de 10% a 500%. Zoom en Excel: de 10% a 400%."},{"id":"x-vo-01-013","origen":"votaciones","test":"Votaciones clase 1","n":13,"enunciado":"Si estamos escribiendo en una celda por primera vez (en una celda en blanco) ¿qué nos muestra la barra de estado?","opciones":["a) Listo","b) Modificar","c) Introducir","d) Escribir"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Barra de estado (pág. 8)","justificaciones":["No. **Listo** aparece en reposo, cuando no se está escribiendo.","No. **Modificar** aparece cuando se edita una celda que ya tenía contenido.","Es esta. **Introducir** aparece cuando se empieza a escribir un nuevo contenido en una celda.","No. “Escribir” no es uno de los estados de la barra de estado."]},{"id":"x-vo-01-014","origen":"votaciones","test":"Votaciones clase 1","n":14,"enunciado":"Señala cuál de las siguientes no es una función del cuadro de nombres:","opciones":["a) Nombrar hojas.","b) Seleccionar celdas.","c) Desplazarnos de celda.","d) Seleccionar una fila."],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Cuadro de nombres (págs. 7 y 8)","justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El cuadro de nombres sirve para nombrar **rangos de celdas**, no hojas. Las hojas se renombran desde su etiqueta.","Es verdadera, así que no se marca. Permite seleccionar un conjunto de celdas.","Es verdadera, así que no se marca. Permite desplazarnos a una celda en concreto, incluso de otras hojas.","Es verdadera, así que no se marca. Permite seleccionar la fila o la columna de la celda activa."]},{"id":"x-vo-01-015","origen":"votaciones","test":"Votaciones clase 1","n":15,"enunciado":"¿Cómo nos desplazamos a la celda A1?","opciones":["a) Pulsando Ctrl + 1","b) Pulsando Ctrl + A + 1","c) Pulsando Ctrl + Inicio","d) Pulsando AvPag"],"correcta":2,"bloque":"excel-general","precepto":"Tema 5 · 3. Desplazamiento por la hoja (pág. 10)","justificaciones":["No. **Ctrl + 1** no sirve para desplazarse. En Excel abre el cuadro Formato de celdas.","No. **Ctrl + A + 1** no es un atajo de desplazamiento.","Es esta. **Ctrl + Inicio** lleva al comienzo de la hoja, la celda A1.","No. **AvPág** baja una pantalla, no va a A1."],"revisar":"Los apuntes (pág. 10) dan Ctrl + Inicio para ir a A1. Que Ctrl + 1 abra Formato de celdas sale del conocimiento general de Excel."},{"id":"x-vo-01-016","origen":"votaciones","test":"Votaciones clase 1","n":16,"enunciado":"Para desplazarnos a la primera celda modificada de la columna activa pulsaremos…","opciones":["a) Pulsando Ctrl + flecha arriba","b) Pulsando Ctrl + flecha derecha","c) Pulsando May + flecha arriba","d) Pulsando May + flecha derecha"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 3. Desplazamiento por la hoja (pág. 10)","justificaciones":["Es esta. **Ctrl + flecha arriba** lleva a la primera celda modificada de la columna activa. Si no hay ninguna, va a la primera celda de la columna.","No. **Ctrl + flecha derecha** lleva a la última celda modificada de la **fila** activa.","No. **Mayús + flecha arriba** amplía la selección hacia arriba, no se desplaza.","No. **Mayús + flecha derecha** amplía la selección hacia la derecha, no se desplaza."],"revisar":"Los apuntes (pág. 10) dicen que Ctrl + flecha arriba lleva a la primera celda modificada de la columna activa. Que Mayús + flecha amplíe la selección sale del conocimiento general de Excel."},{"id":"x-vo-01-017","origen":"votaciones","test":"Votaciones clase 1","n":17,"enunciado":"¿Cómo podemos modificar el contenido de una celda?","opciones":["a) Pulsando F2.","b) Haciendo doble clic en ella.","c) Desde la barra de fórmulas.","d) Todas son correctas."],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 3. Introducción de datos (pág. 12)","justificaciones":["No. Por sí sola no es la respuesta completa: **F2** sirve para modificar los datos sin sustituir todo el contenido, pero también valen las otras dos formas.","No. Por sí sola no es la respuesta completa: el **doble clic** en la celda también permite modificarla, igual que F2 y la barra de fórmulas.","No. Por sí sola no es la respuesta completa: la **barra de fórmulas** también permite modificar el contenido, igual que F2 y el doble clic.","Es esta. Las tres formas valen: **F2**, **doble clic** en la celda o la **barra de fórmulas**."]},{"id":"x-vo-01-018","origen":"votaciones","test":"Votaciones clase 1","n":18,"enunciado":"¿Qué tecla debemos mantener pulsada si queremos hacer una selección discontinua de celdas de una hoja de Excel?","opciones":["a) CTRL","b) MAY","c) TAB","d) Intro"],"correcta":0,"bloque":"excel-general","precepto":"Tema 5 · 3. Selección de celdas (pág. 11)","justificaciones":["Es esta. Para seleccionar celdas o rangos discontinuos se hace clic mientras se mantiene pulsada la tecla **Ctrl**.","No. **Mayús** sirve para ampliar una selección contigua hasta otra celda, no para selecciones discontinuas.","No. **Tab** mueve a la celda de la derecha.","No. **Intro** mueve a la celda de abajo."],"revisar":"Los apuntes (pág. 11) dan Ctrl para la selección discontinua. Que Mayús sirva para ampliar una selección contigua sale del conocimiento general de Excel."},{"id":"x-in-01-055","origen":"oficiales","test":"INAP 2019 ord.","n":55,"enunciado":"Una celda de una hoja Excel contiene la siguiente fórmula (sin comillas): \"=Dato!B1+Resultados!B1\". Si las celdas referenciadas son numéricas, ¿cuál es el resultado de la fórmula?","opciones":["El valor de la celda B1 de la hoja \"Dato\" sumado al valor de la celda B1 de la hoja \"Resultados\". Es necesario que la fórmula se encuentre en una de las dos hojas referenciadas.","El valor de la celda B1 de la hoja \"Dato\" sumado al valor de la celda B1 de la hoja \"Resultados\". Ambas hojas están el mismo libro donde se encuentra la fórmula.","Esta fórmula obtendrá un error, pues no es posible hacer cálculos con los valores situados en celdas que están en hojas diferentes.","El valor de la celda B1 de la hoja \"Dato\" sumado al valor de la celda B1 de la hoja \"Resultados\". Las hojas pueden estar en el mismo libro o en libros diferentes."],"correcta":1,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 55","justificaciones":["","Es esta. La sintaxis **Hoja!Celda** referencia una celda de otra hoja **del mismo libro**. La fórmula **=Dato!B1+Resultados!B1** suma la B1 de la hoja Dato y la B1 de la hoja Resultados, esté donde esté la fórmula.","",""],"ojo":"Para referenciar otro libro, haría falta el nombre del archivo entre corchetes: **=[Libro2.xlsx]Hoja1!B1**. Y sí se pueden hacer cálculos con celdas de hojas distintas."},{"id":"x-in-01-056","origen":"oficiales","test":"INAP 2019 ord.","n":56,"enunciado":"En una hoja de Excel, las celdas A1 y B1 contienen valores numéricos. La celda C1 contiene la siguiente fórmula (sin las comillas): \"=O(A1>B1;A1=B1;A1<B1)\". ¿Cuál será el valor de la celda C1?","opciones":["VERDADERO solo si A1 es mayor que B1.","VERDADERO en todos los casos.","FALSO solo si A1 es menor que B1.","FALSO en todos los casos."],"correcta":1,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 56","justificaciones":["","Es esta. La función **O** devuelve **VERDADERO** si **al menos una** de sus condiciones se cumple. Entre «A1 mayor que B1», «igual» y «menor», siempre se cumple una, así que C1 es **VERDADERO en todos los casos**.","",""],"ojo":"Si la función fuera **Y**, que pide que se cumplan todas, el resultado sería siempre FALSO, porque no pueden cumplirse las tres a la vez."},{"id":"x-in-01-057","origen":"oficiales","test":"INAP 2019 ord.","n":57,"enunciado":"A partir de una fecha en la celda A1 queremos obtener el día del mes correspondiente (un número de 1 a 31). ¿Cuál de las siguientes funciones de Excel utilizaremos?","opciones":["=AHORA(A1)","=DIA(A1)","=DIA.LAB(A1)","=DIAS(A1)"],"correcta":1,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 57","justificaciones":["","Es esta. **DIA(A1)** devuelve el **número de día del mes** (de 1 a 31) de una fecha.","",""],"ojo":"**AHORA** devuelve la fecha y hora actuales y no lleva argumentos, **DIA.LAB** suma días laborables a una fecha y **DIAS** calcula la diferencia entre dos fechas."},{"id":"x-in-01-059","origen":"oficiales","test":"INAP 2019 ord.","n":59,"enunciado":"En una hoja de Excel la celda A1 tiene el valor \"Azul\" y la celda A2 tiene el valor \"Verde\" (ambos sin las comillas). Seleccionamos ambas celdas y pulsamos \"Combinar y centrar\". ¿Cuál será el valor en la celda resultante después de pulsar \"Aceptar\"?","opciones":["Los valores Azul y Verde separados por un espacio y centrados.","El valor Verde centrado.","Se eliminan los valores previos a la combinación de las celdas.","El valor Azul centrado."],"correcta":3,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 59","justificaciones":["","","","Es esta. Al **combinar celdas**, Excel conserva **solo el valor de la celda superior izquierda** y descarta el resto, avisando antes con un cuadro de diálogo. Queda **Azul**, centrado."],"ojo":"Si quieres unir el contenido de varias celdas, usa la función **UNIRCADENAS** o **CONCAT**, no Combinar y centrar."},{"id":"x-in-01-060","origen":"oficiales","test":"INAP 2019 ord.","n":60,"enunciado":"En una hoja Excel la celda A1 contiene el texto \"Referencia 01\" y la celda A2 contiene la fórmula \"=EXTRAE(A1;12;2)\" (ambos sin comillas). ¿Qué resultado obtenemos en la celda A2?","opciones":["Referencia 0","Referencia 01","Re","01"],"correcta":3,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2019 ord. · nº 60","justificaciones":["","","","Es esta. **EXTRAE(texto; posición_inicial; núm_de_caracteres)** toma caracteres desde una posición. En «Referencia 01», «Referencia» ocupa 10 caracteres, el espacio es el 11 y el 0 es el 12, así que dos caracteres desde ahí dan **01**."],"ojo":"La trampa es no contar el espacio. Para el inicio del texto se usa IZQUIERDA y para el final DERECHA."},{"id":"x-in-02-056","origen":"oficiales","test":"INAP 2019 extra","n":56,"enunciado":"En una hoja de Excel queremos extraer la fórmula de la celda A1 y mostrarla, en otra celda, como una cadena de texto. ¿Cuál de las siguientes funciones utilizaremos?","opciones":["=BUSCARH(A1)","=COLUMNA(A1)","=FIELDVALUE(A1)","=FORMULATEXTO(A1)"],"correcta":3,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 56","justificaciones":["","","","Es esta. **FORMULATEXTO(A1)** devuelve la **fórmula** de una celda **como texto**."],"ojo":"**BUSCARH** busca en filas, **COLUMNA** da el número de columna y **FIELDVALUE** no devuelve la fórmula de la celda. Para ver las fórmulas de toda la hoja a la vez, se usa Fórmulas > Mostrar fórmulas."},{"id":"x-in-02-057","origen":"oficiales","test":"INAP 2019 extra","n":57,"enunciado":"En una hoja Excel introducimos el siguiente dato (sin las comillas) en una celda: \"01/01/2021\". A continuación, aplicamos el siguiente formato personalizado (sin las comillas) a la celda: \"mmm-aa\". ¿Qué se visualizará en la celda?","opciones":["ene-21","01/01/2021","44197","01-ene-21"],"correcta":0,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 57","justificaciones":["Es esta. El formato personalizado **mmm-aa** muestra el **mes abreviado de tres letras** y el **año con dos cifras**: **ene-21**. El valor real de la celda no cambia, solo cómo se ve.","","",""],"ojo":"Con **mmmm** saldría el mes completo, con **aaaa** el año de cuatro cifras y con **dd** se vería el día. Si quitas el formato, la fecha sería el número de serie 44197."},{"id":"x-in-02-064","origen":"oficiales","test":"INAP 2019 extra","n":64,"enunciado":"¿Cuál de las siguientes opciones es verdadera con respecto al uso de gráficos de Excel en los mensajes de Outlook?","opciones":["Es posible insertar gráficos en el correo que ya estén hechos en Excel, pero no crearlos desde el editor de mensajes de Outlook, por lo que será necesario primero copiar el gráfico en Excel, luego abrir el mensaje y copiar el gráfico en el cuerpo del mensaje.","Podemos crear un gráfico Excel directamente en un mensaje de Outlook. En el menú Insertar de la ventana del mensaje, en el grupo Ilustraciones, elegir Gráfico. Elegir el tipo de gráfico y hacer clic en Aceptar. En la hoja de cálculo de Excel que aparece escribir los datos del gráfico, y cerrar la hoja.","No es posible insertar gráficos de Excel en un correo de Outlook.","Es posible insertar gráficos en el correo que ya estén hechos en Excel. Es necesario abrir el mensaje en una nueva ventana. A continuación, en el menú Opciones, en el grupo Excel, elegir Gráfico. En la ventana \"Insertar gráfico\", seleccionamos la hoja de Excel donde está el gráfico."],"correcta":1,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2019 extra · nº 64","justificaciones":["","Es esta. En un mensaje de Outlook se puede **crear un gráfico de Excel** directamente: **Insertar > Ilustraciones > Gráfico**, se elige el tipo, se pulsa Aceptar y se escriben los datos en la hoja de Excel que se abre.","",""],"ojo":"No hace falta copiar el gráfico desde Excel, aunque también se puede. Y no existe un grupo «Excel» en la pestaña Opciones del mensaje."},{"id":"x-in-03-053","origen":"oficiales","test":"INAP 2022 ord.","n":53,"enunciado":"¿Cuál de las siguientes opciones NO es una función de Excel 365?","opciones":["PRUEBA.F.N","SI","BUSCAR","PRUEBA"],"correcta":3,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2022 ord. · nº 53","justificaciones":["","","","Es esta. **PRUEBA** no existe como función de Excel. Las otras sí: **PRUEBA.F.N** (prueba F), **SI** (condiciones) y **BUSCAR** (búsquedas)."],"ojo":"Si dudas de si una función existe, fíjate en el nombre exacto: PRUEBA.F.N sí existe, pero PRUEBA sola no. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"x-in-03-054","origen":"oficiales","test":"INAP 2022 ord.","n":54,"enunciado":"Dada la celda A2 con valor 55 y la celda B2 con valor 0, si aplicamos la fórmula en Excel 365: “=SIERROR(A2/B2; \"Error en el cálculo\")”, ¿qué valor obtendremos?","opciones":["0","#¿NOMBRE?","#¡DIV/0!","Error en el cálculo"],"correcta":1,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2022 ord. · nº 54","justificaciones":["","Es esta. En Excel en español la función es **SI.ERROR**, con punto. Escrita como **SIERROR**, Excel no reconoce el nombre y devuelve **#¿NOMBRE?**, sin llegar a calcular la división.","",""],"ojo":"Si estuviera bien escrita, **=SI.ERROR(A2/B2;\"Error en el cálculo\")** mostraría el texto, porque 55/0 da #¡DIV/0!. La trampa es el nombre de la función, no la división. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"x-in-04-057","origen":"oficiales","test":"INAP 2022 extra","n":57,"enunciado":"Si en Excel 365 queremos tener una celda que sólo admita introducir valores de un conjunto predeterminado:","opciones":["Debemos marca la celda de sólo lectura","Debemos aplicar una fórmula","Debemos crear una lista desplegable","Debemos crear una tabla aparte"],"correcta":2,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 57","justificaciones":["","","Es esta. Para que una celda **solo admita valores de un conjunto** previsto, se usa **Validación de datos > Permitir: Lista**, que crea una **lista desplegable**. Está en la pestaña **Datos**.",""],"ojo":"Marcar la celda como solo lectura la bloquea por completo, y una fórmula o una tabla aparte no restringen lo que se escribe. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"x-in-04-058","origen":"oficiales","test":"INAP 2022 extra","n":58,"enunciado":"En una hoja Excel existe una celda que contiene la siguiente fórmula (sin comillas): \"=Presupuesto_1!A2- Presupuesto_2!C3\". ¿Cuál es el resultado de la fórmula si las celdas referenciadas son numéricas?","opciones":["El valor de la celda A2 de la hoja \"Presupuesto_1\" menos el valor de la celda C3 de la hoja \"Presupuesto_2\". Las hojas están en libros diferentes","El valor de la celda A2 de la hoja \"Presupuesto_1\" menos el valor de la celda C3 de la hoja \"Presupuesto_2\". Es necesario que la fórmula se encuentre en una de las dos hojas referenciadas","El valor de la celda A2 de la hoja \"Presupuesto_1\" menos el valor de la celda C3 de la hoja \"Presupuesto_2\". Ambas hojas están el mismo libro donde se encuentra la fórmula","#¡VALOR!, pues no es posible hacer cálculos con valores situados en celdas que están en hojas diferentes"],"correcta":2,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 58","justificaciones":["","","Es esta. El signo **!** separa el nombre de la hoja de la celda **dentro del mismo libro**. La fórmula resta C3 de la hoja Presupuesto_2 a A2 de la hoja Presupuesto_1.",""],"ojo":"Si fueran libros distintos, vería el nombre del archivo entre corchetes. Excel no limita los cálculos entre hojas diferentes."},{"id":"x-in-04-059","origen":"oficiales","test":"INAP 2022 extra","n":59,"enunciado":"En una hoja Excel existe una celda que contiene la siguiente fórmula (sin comillas): “=ESLOGICO(FALSO)\". ¿Cuál es el resultado?","opciones":["Verdadero","Falso","#¡VALOR!","#¿NOMBRE?"],"correcta":0,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 59","justificaciones":["Es esta. **ESLOGICO(valor)** comprueba **si el argumento es un valor lógico** (VERDADERO o FALSO) y devuelve VERDADERO o FALSO. **FALSO** es un valor lógico, así que el resultado es **VERDADERO**.","","",""],"ojo":"La trampa es leer la función como si devolviera el valor del argumento. ESLOGICO no mira si es verdadero o falso, sino si es del tipo lógico."},{"id":"x-in-04-060","origen":"oficiales","test":"INAP 2022 extra","n":60,"enunciado":"Si estamos trabajando con Excel 365 , ¿qué resultado se obtendrá con la siguiente fórmula “=MAX(77,12,81,23)”?","opciones":["77","Error","81","23"],"correcta":1,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2022 extra · nº 60","justificaciones":["","Es esta. En la versión **española** de Excel, los argumentos de una función se separan con **punto y coma**. **=MAX(77,12,81,23)** con comas da **error**, porque Excel lee 77,12 como un número decimal. Correcto: **=MAX(77;12;81;23)**, que devolvería 81.","",""],"ojo":"Si la pregunta usa comas entre argumentos y Excel está en español, sospecha del error. En la versión inglesa sí se usan comas. Oficial actualizada: el INAP la redactó para una versión anterior de Windows u Office y aquí está adaptada a Windows 11 y Microsoft 365."},{"id":"x-in-05-058","origen":"oficiales","test":"INAP 14 dic. 2024","n":58,"enunciado":"¿Cuál es la utilidad de la función de segmentación de datos en Excel 365?","opciones":["Es una función que permite realizar operaciones de cálculo sobre una columna numérica.","Permite dividir una tabla de origen en varias tablas de destino separadas, según un criterio de segmentación.","Permite realizar cálculos financieros utilizando varias columnas de una tabla.","Es una función que permite filtrar datos de manera interactiva en tablas o tablas dinámicas."],"correcta":3,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 58","justificaciones":["","","","Es esta. La **segmentación de datos** son botones que **filtran datos de forma visual e interactiva** en **tablas** y **tablas dinámicas**. Se insertan desde Insertar > Filtros > Segmentación de datos."],"ojo":"No divide tablas en varias, no hace operaciones de cálculo y no es una función financiera. Los botones muestran qué filtro está activo."},{"id":"x-in-05-059","origen":"oficiales","test":"INAP 14 dic. 2024","n":59,"enunciado":"En un libro de Excel 365 tenemos varias hojas y en la hoja activa varias tablas de las cuales hemos seleccionado una. ¿Cuál de las siguientes opciones debemos elegir para imprimir solo esta tabla?","opciones":["Imprimir todo el libro.","Imprimir hojas activas.","Imprimir selección.","Imprimir todas las hojas."],"correcta":2,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 59","justificaciones":["","","Es esta. Con la tabla seleccionada, en **Archivo > Imprimir** se elige **Imprimir selección**, y solo se imprime esa tabla.",""],"ojo":"Las demás opciones imprimen más: **hojas activas** imprime las hojas seleccionadas, y **todo el libro** o **todas las hojas** imprimen todo."},{"id":"x-in-05-060","origen":"oficiales","test":"INAP 14 dic. 2024","n":60,"enunciado":"En una hoja de Excel 365 en idioma español, en una celda a la cual no se le ha aplicado ningún tipo de formato, escribimos el siguiente valor: 20-2 ¿Cuál de las siguientes opciones es la que mostrará tras pulsar la tecla Enter?","opciones":["20-feb","18","20-2","45342,00"],"correcta":0,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 60","justificaciones":["Es esta. Si escribes **20-2** en una celda sin formato, Excel lo interpreta como una **fecha** y muestra **20-feb** (20 de febrero del año actual). El valor guardado es el número de serie de esa fecha.","","",""],"ojo":"No es una resta: para que lo fuera haría falta empezar con **=**. Si el formato de celda fuera Texto, se vería 20-2."},{"id":"x-in-05-067","origen":"oficiales","test":"INAP 14 dic. 2024","n":67,"enunciado":"En una tabla de Excel 365 queremos convertir algunas columnas en filas de una tabla dinámica. ¿Cuál de las siguientes funciones de Power Query nos servirá para hacerlo?","opciones":["Duplicar columnas.","Agrupar por.","Anulación de dinamización de columnas.","Invertir filas."],"correcta":2,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 14 dic. 2024 · nº 67","justificaciones":["","","Es esta. En **Power Query**, la función **Anular dinamización de columnas** convierte **columnas en filas**: transforma varias columnas en pares de atributo y valor. Está en la pestaña Transformar.",""],"ojo":"Es la inversa de **dinamizar columnas**. **Agrupar por** resume filas y **Duplicar columnas** copia, y ninguna convierte columnas en filas."},{"id":"x-in-06-062","origen":"oficiales","test":"INAP 2024 extra","n":62,"enunciado":"Queremos asegurarnos de que al imprimir una hoja de Excel solo tenga una página de ancho, aunque pueda tener varias páginas de largo. ¿Cuál de las siguientes opciones deberemos elegir?","opciones":["Ajustar todas las filas en una página.","Sin escalado.","Ajustar hoja en una página.","Ajustar todas las columnas en una página."],"correcta":3,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 62","justificaciones":["","","","Es esta. Para imprimir **una sola página de ancho** y las que hagan falta de largo, en **Archivo > Imprimir > Escala** se elige **Ajustar todas las columnas en una página**."],"ojo":"**Ajustar hoja en una página** comprime también el alto, y **Ajustar todas las filas en una página** hace una sola página de alto. **Sin escalado** no cambia nada."},{"id":"x-in-06-063","origen":"oficiales","test":"INAP 2024 extra","n":63,"enunciado":"En Excel 365, tenemos en la celda H44 el texto: \"Mochila-azul\". En la celda J44 tenemos la siguiente fórmula: =DIVIDIRTEXTO(H44;\"-\"). ¿Cuál de las siguientes opciones describe correctamente el efecto de la fórmula?","opciones":["Extrae una parte del texto, hasta el carácter de guion: \"-\", dando como resultado para la celda J44 el texto: \"Mochila\".","Divide el texto separándolo por el carácter de guion: \"-\". En la celda J44 aparecerá el texto: \"Mochila\" y en la K44, el texto: \"azul\".","Extrae el texto a partir del carácter de división, en este caso, el guion: \"-\", por lo que la celda J44 mostrará el texto: \"azul\".","Divide el texto separándolo por el carácter de guion: y lo sustituye por un espacio en blanco entre las dos cadenas de texto. En la celda J44 aparecerá el texto: \"Mochila azul\"."],"correcta":1,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 2024 extra · nº 63","justificaciones":["","Es esta. **DIVIDIRTEXTO** **reparte un texto en varias celdas** usando el delimitador indicado. Con **=DIVIDIRTEXTO(H44;\"-\")**, «Mochila-azul» queda como **«Mochila»** en J44 y **«azul»** en K44, porque el resultado se derrama a la derecha.","",""],"ojo":"No extrae solo una parte ni sustituye el guion por un espacio. Es una función de Excel 365 reciente, y por eso no existe en versiones antiguas."},{"id":"x-in-07-055","origen":"oficiales","test":"INAP 23 mayo 2026","n":55,"enunciado":"En una celda de Excel 365 tenemos la siguiente fórmula: =FILAS(Registros[Fecha]). Si el resultado que muestra es 5, indique cuál es el funcionamiento de la fórmula:","opciones":["Establece para las filas seleccionadas de la tabla Registros el formato de fecha.","Devuelve la diferencia de días en las fechas de la columna Registros.","Establece un máximo de filas, en este caso 5, admisibles en la columna Fecha.","Devuelve el número de filas de la columna Fecha en la tabla Registros."],"correcta":3,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 55","justificaciones":["","","","Es esta. **FILAS(Registros[Fecha])** **devuelve el número de filas** de la referencia que se le pasa. **Registros[Fecha]** es la **columna Fecha de la tabla Registros**, así que si el resultado es 5, la columna tiene 5 filas."],"ojo":"No da formato ni diferencia de días, ni pone un máximo. **COLUMNAS** haría lo mismo con las columnas."},{"id":"x-in-07-056","origen":"oficiales","test":"INAP 23 mayo 2026","n":56,"enunciado":"En Excel 365, ¿cuál de los siguientes valores es correcto si aplicamos el siguiente formato de fecha a una celda: dd/mmm/aa?","opciones":["11/agosto/24","11/agosto/2024","Once de agosto del año 2024","11/ago/24"],"correcta":3,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 56","justificaciones":["","","","Es esta. El formato **dd/mmm/aa** muestra el **día con dos cifras**, el **mes abreviado de tres letras** y el **año con dos cifras**: **11/ago/24**."],"ojo":"Con **mmmm** saldría «agosto», con **aaaa** «2024». Para recordarlo: una m o dos m son el número, tres m es el nombre abreviado y cuatro m es el nombre completo."},{"id":"x-in-07-057","origen":"oficiales","test":"INAP 23 mayo 2026","n":57,"enunciado":"En Excel 365, al trabajar con rangos, ¿cuál de las siguientes opciones describe correctamente un rango discontinuo?","opciones":["B2:B2","$B$2:$C$4","B2:C4","B2:C2;B4:C4"],"correcta":3,"bloque":"excel-general","precepto":"Tema 5 · 2. Interfaz de Excel, Área de trabajo (pág. 6)","justificaciones":["No. B2:B2 es una sola celda, un rango de una celda.","No. $B$2:$C$4 es un rango continuo, con referencias absolutas.","No. B2:C4 es un rango continuo: todas las celdas son contiguas.","Es esta. Un rango **discontinuo** está formado por dos o más áreas no adyacentes, separadas por punto y coma: **B2:C2;B4:C4**. Se seleccionan con la tecla Ctrl."],"dup":"x-of-01-004"},{"id":"x-in-07-058","origen":"oficiales","test":"INAP 23 mayo 2026","n":58,"enunciado":"¿Qué función de Excel 365 se encarga de invertir el valor lógico de su argumento?","opciones":["NO","CAMBIAR","ESLOGICO","MINVERSA"],"correcta":0,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · 23 mayo 2026 · nº 58","justificaciones":["Es esta. La función **NO** **invierte el valor lógico** de su argumento: **NO(FALSO)** devuelve VERDADERO y **NO(VERDADERO)** devuelve FALSO.","","",""],"ojo":"**ESLOGICO** solo comprueba si el valor es lógico, y **MINVERSA** calcula la inversa de una matriz. **CAMBIAR** busca un valor y lo sustituye por otro."},{"id":"x-in-08-056","origen":"oficiales","test":"INAP julio 2026 extra","n":56,"enunciado":"Si en Excel 365 copiamos una fórmula que contiene la referencia relativa A1 desde una celda hacia la celda inmediatamente inferior (hacia abajo), ¿qué sucede con dicha referencia en la nueva ubicación?","opciones":["La referencia se ajusta automáticamente y cambia en la celda inferior.","La referencia se convierte automáticamente en absoluta.","La referencia permanece bloqueada como A1 en la nueva celda.","La fórmula genera un error de referencia al cambiar de fila."],"correcta":0,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · julio 2026 extra · nº 56","justificaciones":["Es esta. Una **referencia relativa** se **ajusta al copiar** la fórmula. Al copiarla una fila hacia abajo, **A1 pasa a A2**.","","",""],"ojo":"Para que no cambie hay que fijarla con **$** (por ejemplo, **$A$1**), y se alterna con **F4**. No da error al copiarse."},{"id":"x-in-08-057","origen":"oficiales","test":"INAP julio 2026 extra","n":57,"enunciado":"En Excel 365, ¿cuál es la causa más probable de que aparezca el error #N/A en una celda?","opciones":["División entre cero.","Valor no disponible en una búsqueda.","Cuando se utiliza un operador de rango incorrecto.","Uso incorrecto de paréntesis."],"correcta":1,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · julio 2026 extra · nº 57","justificaciones":["","Es esta. El error **#N/A** significa **valor no disponible**: es el típico de **BUSCARV**, **BUSCARX** o COINCIDIR cuando **no encuentran** lo que buscan.","",""],"ojo":"Cada error tiene su causa: **#¡DIV/0!** es dividir entre cero, **#¿NOMBRE?** es una función mal escrita, **#¡VALOR!** es un tipo de dato equivocado y **#¡REF!** es una referencia rota."},{"id":"x-in-08-058","origen":"oficiales","test":"INAP julio 2026 extra","n":58,"enunciado":"En Excel 365, ¿qué diferencia hay entre las funciones CONTAR y CONTARA?","opciones":["CONTAR cuenta celdas con número y CONTARA cuenta las celdas en blanco.","CONTAR suma el contenido númerico de las celdas y CONTARA cuenta las celdas en blanco.","CONTAR cuenta celdas con número y CONTARA cuenta todas las celdas no vacías.","CONTAR suma el contenido númerico de las celdas y CONTARA cuenta todas las celdas no vacías."],"correcta":2,"bloque":"excel-general","precepto":"Pregunta oficial del INAP · julio 2026 extra · nº 58","justificaciones":["","","Es esta. **CONTAR** cuenta solo las celdas con **números**. **CONTARA** cuenta **todas las celdas no vacías**, sean números, texto, errores o lo que sea.",""],"ojo":"Para contar celdas **en blanco** se usa **CONTAR.BLANCO**. Ni CONTAR ni CONTARA suman valores: para sumar está SUMA."}]});
